import { expect, Page } from '@playwright/test';

/**
 * Page Object — Sign up · Zennx Demo Store.
 * https://zennx.dev/demo-ecommerse/signup
 *
 * Generated by the Zennx Playwright studio from a recorded session.
 * Locators live here and nowhere else, so a renamed button is one edit.
 */
export class DemoEcommerseSignupPage {
    readonly page: Page;

    private readonly createYourAccountHeading = () => this.page.getByRole('heading', { name: 'Create your account' });
    private readonly inputName = () => this.page.getByTestId('input-name');
    private readonly inputEmail = () => this.page.getByTestId('input-email');
    private readonly inputPassword = () => this.page.getByTestId('input-password');
    private readonly inputConfirm = () => this.page.getByTestId('input-confirm');
    private readonly inputTerms = () => this.page.getByTestId('input-terms');
    private readonly signupSubmit = () => this.page.getByTestId('signup-submit');

    constructor(page: Page) {
        this.page = page;
    }

    async expectCreateYourAccountHeadingVisible(): Promise<void> {
        await expect(this.createYourAccountHeading()).toBeVisible();
    }

    async fillInputName(value: string): Promise<void> {
        await this.inputName().fill(value);
    }

    async fillInputEmail(value: string): Promise<void> {
        await this.inputEmail().fill(value);
    }

    async fillInputPassword(value: string): Promise<void> {
        await this.inputPassword().fill(value);
    }

    async fillInputConfirm(value: string): Promise<void> {
        await this.inputConfirm().fill(value);
    }

    async setInputTerms(checked: boolean): Promise<void> {
        if (checked) await this.inputTerms().check();
        else await this.inputTerms().uncheck();
    }

    async clickSignupSubmit(): Promise<void> {
        await this.signupSubmit().click();
    }
}
